const c = $('Configure this batch').first().json;
const normalize = value => String(value ?? '').trim().toLowerCase().replace(/^https?:\/\//, '').split('/')[0].replace(/^www\./, '');
const rows=$input.all().map(i=>i.json).filter(r=>String(r.Domain??'').trim());
if(!rows.length)return [];
if(rows.length>5)throw new Error('Use at most 5 leads per batch.');
const values=rows.map(r=>normalize(r.Domain));
if(new Set(values).size!==values.length)throw new Error('Domain cells must be unique after normalization.');
if(values.some(v=>!v || v.includes('your_')))throw new Error('Replace domain placeholders.');
return [{json:{...c,domains:values}}];

const day = $now.toFormat('yyyy-MM-dd');
const normalize = value => String(value ?? '').trim().toLowerCase().replace(/^https?:\/\//, '').split('/')[0].replace(/^www\./, '');
const sources=$('Read lead rows').all().map(i=>i.json);
return $input.all().filter(i=>i.json.domain).map(({json:d})=>{
const source=sources.find(r=>normalize(r.Domain)===normalize(d.domain));
if(!source)throw new Error('Report domain did not match an input row.');
return {json:{Domain:source.Domain,'Intent score':d.intent_score??'','Open jobs':d.open_jobs??'','Ads running now':d.ads_running_now??'',Summary:d.summary??'','Checked on':day}};
});
